"use client";

import { createContext, useContext, useState } from "react";
import { usePathname } from "next/navigation";

import type { AppHeaderContextValue, NavItem } from "./types";

const AppHeaderContext = createContext<AppHeaderContextValue | null>(null);

export function useAppHeader() {
	const context = useContext(AppHeaderContext);
	if (!context) {
		throw new Error("useAppHeader must be used within an AppHeaderProvider");
	}
	return context;
}

interface AppHeaderProviderProps {
	children: React.ReactNode;
	navItems?: NavItem[];
}

export function AppHeaderProvider({
	children,
	navItems = [],
}: AppHeaderProviderProps) {
	const currentPath = usePathname();
	const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

	return (
		<AppHeaderContext.Provider
			value={{
				navItems,
				currentPath,
				mobileMenuOpen,
				setMobileMenuOpen,
			}}
		>
			{children}
		</AppHeaderContext.Provider>
	);
}

