"use client";

import Link from "next/link";

import { cn } from "@/lib/utils";

import { useAppHeader } from "./context";

export function HeaderNav() {
	const { navItems, currentPath } = useAppHeader();

	if (navItems.length === 0) {
		return null;
	}

	return (
		<nav className="hidden items-center gap-1 md:flex">
			{navItems.map((item) => {
				const isActive = currentPath === item.href;
				return (
					<Link
						key={item.href}
						href={item.disabled ? "#" : item.href}
						aria-current={isActive ? "page" : undefined}
						aria-disabled={item.disabled}
						className={cn(
							"relative inline-flex h-9 items-center gap-2 px-4 py-2 text-sm font-medium transition-colors hover:bg-accent hover:text-accent-foreground",
							isActive && "bg-accent text-accent-foreground",
							item.disabled && "pointer-events-none opacity-50",
						)}
					>
						{item.icon}
						{item.label}
						{item.badge != null && (
							<span className="rounded-full bg-primary px-1.5 py-0.5 text-xs text-primary-foreground">
								{item.badge}
							</span>
						)}
						{isActive && (
							<span className="absolute right-4 bottom-0 left-4 h-0.5 bg-primary" />
						)}
					</Link>
				);
			})}
		</nav>
	);
}

