    71→			});
    72→		},
    73→		validators: {
    74→			onSubmit: createSurveySchema,
    75→		},
    76→	});
    77→
    78→	return (
    79→		<div className="mx-auto w-full max-w-2xl p-6">
    80→			<div className="mb-6">
    81→				<Button variant="ghost" size="sm" asChild>
    82→					<Link href="/surveys">
    83→						<ArrowLeft className="mr-2 h-4 w-4" />
    84→						Back to Surveys
    85→					</Link>
    86→				</Button>
    87→			</div>
    88→
    89→			<Card>
    90→				<CardHeader>
    91→					<CardTitle>Create New Survey</CardTitle>
    92→					<CardDescription>
    93→						Set up a new survey to start collecting responses
    94→					</CardDescription>
    95→				</CardHeader>
    96→				<CardContent>
    97→					<form
    98→						onSubmit={(e) => {
    99→							e.preventDefault();
   100→							e.stopPropagation();
   101→							form.handleSubmit();
   102→						}}
   103→						className="space-y-6"
   104→					>
   105→						<form.Field name="title">
   106→							{(field) => (
   107→								<div className="space-y-2">
   108→									<Label htmlFor={field.name}>Title *</Label>
   109→									<Input
   110→										id={field.name}
   111→										name={field.name}
   112→										placeholder="e.g., Customer Feedback Survey"
   113→										value={field.state.value}
   114→										onBlur={field.handleBlur}
   115→										onChange={(e) => {
   116→											field.handleChange(e.target.value);
   117→											// Auto-generate slug if empty
   118→											if (!form.getFieldValue("slug")) {
   119→												form.setFieldValue(
   120→													"slug",
   121→													generateSlug(e.target.value),
   122→												);
   123→											}
   124→										}}
   125→									/>
   126→									{field.state.meta.errors.length > 0 && (
   127→										<p className="text-red-500 text-sm">
   128→											{String(field.state.meta.errors[0])}
   129→										</p>
   130→									)}
   131→								</div>
   132→							)}
   133→						</form.Field>
   134→
   135→						<form.Field name="slug">
   136→							{(field) => (
   137→								<div className="space-y-2">
   138→									<Label htmlFor={field.name}>URL Slug *</Label>
   139→									<div className="flex items-center">
   140→										<span className="shrink-0 rounded-l-md border border-neutral-200 border-r-0 bg-neutral-50 px-3 py-2 text-neutral-500 text-sm">
   141→											/survey/
   142→										</span>
   143→										<Input
   144→											id={field.name}
   145→											name={field.name}
   146→											placeholder="customer-feedback"
   147→											value={field.state.value}
   148→											onBlur={field.handleBlur}
   149→											onChange={(e) => field.handleChange(e.target.value)}
   150→											className="rounded-l-none"
   151→										/>
   152→									</div>
   153→									<p className="text-neutral-500 text-xs">
   154→										Unique identifier for your survey URL. Use lowercase
   155→										letters, numbers, and hyphens.
   156→									</p>
   157→									{field.state.meta.errors.length > 0 && (
   158→										<p className="text-red-500 text-sm">
   159→											{String(field.state.meta.errors[0])}
   160→										</p>
   161→									)}
   162→								</div>
   163→							)}
   164→						</form.Field>
   165→
   166→						<form.Field name="description">
   167→							{(field) => (
   168→								<div className="space-y-2">
   169→									<Label htmlFor={field.name}>Description</Label>
   170→									<Textarea
   171→										id={field.name}
   172→										name={field.name}
   173→										placeholder="Describe the purpose of this survey..."
   174→										value={field.state.value}
   175→										onBlur={field.handleBlur}
   176→										onChange={(e) => field.handleChange(e.target.value)}
   177→										rows={3}
   178→									/>
   179→									{field.state.meta.errors.length > 0 && (
   180→										<p className="text-red-500 text-sm">
   181→											{String(field.state.meta.errors[0])}
   182→										</p>
   183→									)}
   184→								</div>
   185→							)}
   186→						</form.Field>
   187→
   188→						<form.Subscribe>
   189→							{(state) => (
   190→								<div className="flex gap-3 pt-4">
   191→									<Button
   192→										type="button"
   193→										variant="outline"
   194→										onClick={() => router.push("/surveys")}
   195→									>
   196→										Cancel
   197→									</Button>
   198→									<Button
   199→										type="submit"
   200→										disabled={!state.canSubmit || state.isSubmitting}
   201→									>
   202→										{state.isSubmitting ? (
   203→											<>
   204→												<Loader2 className="mr-2 h-4 w-4 animate-spin" />
   205→												Creating...
   206→											</>
   207→										) : (
   208→											"Create Survey"
   209→										)}
   210→									</Button>
   211→								</div>
   212→							)}
   213→						</form.Subscribe>
   214→					</form>
   215→				</CardContent>
   216→			</Card>
   217→		</div>
   218→	);
   219→}
