"use client";

import { Menu } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";

import { authClient } from "@/lib/auth-client";
import { Button } from "@/components/ui/button";
import {
	Sheet,
	SheetContent,
	SheetHeader,
	SheetTitle,
	SheetTrigger,
} from "@/components/ui/sheet";

import { useAppHeader } from "./context";
import { cn } from "@/lib/utils";

export function MobileMenu() {
	const { navItems, currentPath, mobileMenuOpen, setMobileMenuOpen } =
		useAppHeader();
	const router = useRouter();

	const handleSignOut = () => {
		authClient.signOut({
			fetchOptions: {
				onSuccess: () => {
					router.push("/");
				},
			},
		});
	};

	return (
		<Sheet open={mobileMenuOpen} onOpenChange={setMobileMenuOpen}>
			<SheetTrigger
				render={
					<Button
						variant="ghost"
						size="icon"
						className="md:hidden"
						aria-label="Open menu"
					/>
				}
			>
				<Menu />
			</SheetTrigger>
			<SheetContent side="left" className="w-72 p-0">
				<SheetHeader className="border-b p-4">
					<SheetTitle className="text-left">Navigation</SheetTitle>
				</SheetHeader>
				<nav className="flex flex-col p-2">
					{navItems.map((item) => {
						const isActive = currentPath === item.href;
						return (
							<Link
								key={item.href}
								href={item.href as never}
								aria-current={isActive ? "page" : undefined}
								onClick={() => setMobileMenuOpen(false)}
								className={cn(
									"flex items-center gap-3 rounded-md px-3 py-2.5 text-sm font-medium transition-colors hover:bg-accent hover:text-accent-foreground",
									isActive && "bg-accent text-accent-foreground",
									item.disabled && "pointer-events-none opacity-50",
								)}
							>
								{item.icon && <span className="shrink-0">{item.icon}</span>}
								{item.label}
								{item.badge != null && (
									<span className="ml-auto rounded-full bg-primary px-1.5 py-0.5 text-xs text-primary-foreground">
										{item.badge}
									</span>
								)}
							</Link>
						);
					})}
				</nav>
				<div className="mt-auto border-t p-2">
					<Button
						variant="destructive"
						className="w-full justify-start"
						onClick={handleSignOut}
					>
						Sign Out
					</Button>
				</div>
			</SheetContent>
		</Sheet>
	);
}

