				search: search || undefined,
				status: statusFilter,
			},
		}),
	);

	const deleteMutation = useMutation(
		orpc.survey.delete.mutationOptions({
			onSuccess: () => {
				toast.success("Survey deleted");
				queryClient.invalidateQueries({ queryKey: ["survey", "list"] });
			},
			onError: (error) => {
				toast.error(error.message || "Failed to delete survey");
			},
		}),
	);

	const changeStatusMutation = useMutation(
		orpc.survey.changeStatus.mutationOptions({
			onSuccess: () => {
				toast.success("Survey status updated");
				queryClient.invalidateQueries({ queryKey: ["survey", "list"] });
			},
			onError: (error) => {
				toast.error(error.message || "Failed to update status");
			},
		}),
	);

	const handleDelete = (id: string) => {
		if (confirm("Are you sure you want to delete this survey?")) {
			deleteMutation.mutate({ id });
		}
	};

	const handleStatusChange = (
		id: string,
		status: "draft" | "published" | "closed" | "archived",
	) => {
		changeStatusMutation.mutate({ id, status });
	};

	return (
		<div className="mx-auto w-full max-w-6xl p-6">
			<div className="mb-8 flex items-center justify-between">
				<div>
					<h1 className="font-bold text-2xl text-foreground">Surveys</h1>
					<p className="text-muted-foreground">Create and manage your surveys</p>
				</div>
				<Button render={<Link href="/surveys/new" />}>
					<Plus className="mr-2 h-4 w-4" />
					Create Survey
				</Button>
			</div>

			{/* Filters */}
			<div className="mb-6 flex flex-wrap items-center gap-4">
				<div className="relative min-w-[200px] flex-1">
					<Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
					<Input
						placeholder="Search surveys..."
						value={search}
						onChange={(e) => {
							setSearch(e.target.value);
							setPage(1);
						}}
						className="pl-10"
					/>
				</div>
				<div className="flex gap-2">
					{(["draft", "published", "closed", "archived"] as const).map(
						(status) => (
							<Button
								key={status}
								variant={statusFilter === status ? "default" : "outline"}
								size="sm"
								onClick={() => {
									setStatusFilter(statusFilter === status ? undefined : status);
									setPage(1);
								}}
							>
								{status.charAt(0).toUpperCase() + status.slice(1)}
							</Button>
						),
					)}
				</div>
			</div>

			{/* Survey List */}
			{surveys.isLoading ? (
				<div className="flex justify-center py-12">
					<Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
				</div>
			) : surveys.data?.data.length === 0 ? (
				<Card className="border-dashed">
					<CardContent className="flex flex-col items-center justify-center py-16">
						<ClipboardList className="mb-4 h-12 w-12 text-muted-foreground/50" />
						<CardTitle className="mb-2">No surveys yet</CardTitle>
						<CardDescription className="mb-4 text-center">
							Create your first survey to start collecting responses
						</CardDescription>
						<Button asChild>
							<Link href="/surveys/new">
								<Plus className="mr-2 h-4 w-4" />
								Create Survey
							</Link>
						</Button>
					</CardContent>
				</Card>
			) : (
				<div className="space-y-4">
					{surveys.data?.data.map((survey) => (
						<Card
							key={survey.id}
							className="transition-colors hover:border-border/80"
						>
							<CardHeader className="pb-3">
								<div className="flex items-start justify-between">
									<div className="flex-1">
										<div className="flex items-center gap-3">
											<Link
												href={`/surveys/${survey.id}`}
												className="font-semibold text-lg hover:text-primary"
											>
												{survey.title}
											</Link>
											<Badge
												variant="secondary"
												className={statusColors[survey.status]}
											>
												{survey.status}
											</Badge>
										</div>
										{survey.description && (
											<CardDescription className="mt-1">
												{survey.description}
											</CardDescription>
										)}
									</div>
									<DropdownMenu>
										<DropdownMenuTrigger
											render={<Button variant="ghost" size="icon" />}
										>
											<MoreHorizontal className="h-4 w-4" />
										</DropdownMenuTrigger>
										<DropdownMenuContent align="end">
											<DropdownMenuItem>
												<Link
													href={`/surveys/${survey.id}`}
													className="flex items-center"
												>
													<Edit className="mr-2 h-4 w-4" />
													Edit
												</Link>
											</DropdownMenuItem>
											<DropdownMenuItem>
												<Link
													href={{
														pathname: `/surveys/${survey.id}/analytics`,
													}}
													className="flex items-center"
												>
													<BarChart3 className="mr-2 h-4 w-4" />
													Analytics
												</Link>
											</DropdownMenuItem>
											{survey.status === "draft" && (
												<DropdownMenuItem
													onClick={() =>
														handleStatusChange(survey.id, "published")
													}
												>
													<ClipboardList className="mr-2 h-4 w-4" />
													Publish
												</DropdownMenuItem>
											)}
											{survey.status === "published" && (
												<DropdownMenuItem
													onClick={() =>
														handleStatusChange(survey.id, "closed")
													}
												>
													<Archive className="mr-2 h-4 w-4" />
													Close
												</DropdownMenuItem>
											)}
											<DropdownMenuSeparator />
											<DropdownMenuItem
												variant="destructive"
												onClick={() => handleDelete(survey.id)}
											>
												<Trash2 className="mr-2 h-4 w-4" />
												Delete
											</DropdownMenuItem>
										</DropdownMenuContent>
									</DropdownMenu>
								</div>
							</CardHeader>
							<CardContent>
								<div className="flex items-center gap-6 text-muted-foreground text-sm">
									<div className="flex items-center gap-1">
										<Calendar className="h-4 w-4" />
										{new Date(survey.createdAt).toLocaleDateString()}
									</div>
									<div className="flex items-center gap-1">
										<ClipboardList className="h-4 w-4" />/{survey.slug}
									</div>
								</div>
							</CardContent>
						</Card>
					))}
				</div>
			)}

			{/* Pagination */}
			{surveys.data && surveys.data.pagination.totalPages > 1 && (
				<div className="mt-6 flex justify-center gap-2">
					<Button
						variant="outline"
						size="sm"
						disabled={page === 1}
						onClick={() => setPage(page - 1)}
					>
						Previous
					</Button>
					<span className="flex items-center px-4 text-sm">
						Page {page} of {surveys.data.pagination.totalPages}
					</span>
					<Button
						variant="outline"
						size="sm"
						disabled={page >= surveys.data.pagination.totalPages}
						onClick={() => setPage(page + 1)}
					>
						Next
					</Button>
				</div>
			)}
		</div>
	);
}

"use client";

import { useForm } from "@tanstack/react-form";
import { useMutation } from "@tanstack/react-query";
import { ArrowLeft, Loader2 } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import z from "zod";

import { Button } from "@/components/ui/button";
import {
	Card,
	CardContent,
	CardDescription,
	CardHeader,
	CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { orpc } from "@/utils/orpc";

const createSurveySchema = z.object({
	slug: z
		.string()
		.min(1, "Slug is required")
		.max(100)
		.regex(
			/^[a-z0-9-]+$/,
			"Slug can only contain lowercase letters, numbers, and hyphens",
		),
	title: z.string().min(1, "Title is required").max(255),
	description: z.string().max(2000),
});

function generateSlug(title: string): string {
	return title
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-|-$/g, "")
		.slice(0, 50);
}

export default function NewSurveyPage() {
	const router = useRouter();

	const createMutation = useMutation(
		orpc.survey.create.mutationOptions({
			onSuccess: (data) => {
				toast.success("Survey created");
				router.push(`/surveys/${data.id}`);
			},
			onError: (error) => {
				toast.error(error.message || "Failed to create survey");
			},
		}),
	);

	const form = useForm({
		defaultValues: {
			slug: "",
			title: "",
			description: "",
		},
		onSubmit: async ({ value }) => {
			await createMutation.mutateAsync({
				slug: value.slug || generateSlug(value.title),
				title: value.title,
				description: value.description || undefined,
			});
		},
		validators: {
			onSubmit: createSurveySchema,
		},
	});

	return (
		<div className="mx-auto w-full max-w-2xl p-6">
			<div className="mb-6">
				<Button variant="ghost" size="sm" asChild>
					<Link href="/surveys">
						<ArrowLeft className="mr-2 h-4 w-4" />
						Back to Surveys
					</Link>
				</Button>
			</div>

			<Card>
				<CardHeader>
					<CardTitle>Create New Survey</CardTitle>
					<CardDescription>
						Set up a new survey to start collecting responses
					</CardDescription>
				</CardHeader>
				<CardContent>
					<form
						onSubmit={(e) => {
							e.preventDefault();
							e.stopPropagation();
							form.handleSubmit();
						}}
						className="space-y-6"
					>
						<form.Field name="title">
							{(field) => (
								<div className="space-y-2">
									<Label htmlFor={field.name}>Title *</Label>
									<Input
										id={field.name}
										name={field.name}
										placeholder="e.g., Customer Feedback Survey"
										value={field.state.value}
										onBlur={field.handleBlur}
										onChange={(e) => {
											field.handleChange(e.target.value);
											// Auto-generate slug if empty
											if (!form.getFieldValue("slug")) {
												form.setFieldValue(
													"slug",
													generateSlug(e.target.value),
												);
											}
										}}
									/>
									{field.state.meta.errors.length > 0 && (
										<p className="text-destructive text-sm">
											{String(field.state.meta.errors[0])}
										</p>
									)}
								</div>
							)}
						</form.Field>

						<form.Field name="slug">
							{(field) => (
								<div className="space-y-2">
									<Label htmlFor={field.name}>URL Slug *</Label>
									<div className="flex items-center">
										<span className="shrink-0 rounded-l-md border border-r-0 bg-muted px-3 py-2 text-muted-foreground text-sm">
											/survey/
										</span>
										<Input
											id={field.name}
											name={field.name}
											placeholder="customer-feedback"
											value={field.state.value}
											onBlur={field.handleBlur}
											onChange={(e) => field.handleChange(e.target.value)}
											className="rounded-l-none"
										/>
									</div>
									<p className="text-muted-foreground text-xs">
										Unique identifier for your survey URL. Use lowercase
										letters, numbers, and hyphens.
									</p>
									{field.state.meta.errors.length > 0 && (
										<p className="text-destructive text-sm">
											{String(field.state.meta.errors[0])}
										</p>
									)}
								</div>
							)}
						</form.Field>

						<form.Field name="description">
							{(field) => (
								<div className="space-y-2">
									<Label htmlFor={field.name}>Description</Label>
									<Textarea
										id={field.name}
										name={field.name}
										placeholder="Describe the purpose of this survey..."
										value={field.state.value}
										onBlur={field.handleBlur}
										onChange={(e) => field.handleChange(e.target.value)}
										rows={3}
									/>
									{field.state.meta.errors.length > 0 && (
										<p className="text-destructive text-sm">
											{String(field.state.meta.errors[0])}
										</p>
									)}
								</div>
							)}
						</form.Field>

						<form.Subscribe>
							{(state) => (
								<div className="flex gap-3 pt-4">
									<Button
										type="button"
										variant="outline"
										onClick={() => router.push("/surveys")}
									>
										Cancel
									</Button>
									<Button
										type="submit"
										disabled={!state.canSubmit || state.isSubmitting}
									>
										{state.isSubmitting ? (
											<>
												<Loader2 className="mr-2 h-4 w-4 animate-spin" />
												Creating...
											</>
										) : (
											"Create Survey"
										)}
									</Button>
								</div>
							)}
						</form.Subscribe>
					</form>
				</CardContent>
			</Card>
		</div>
	);
}

