     2→
     3→import type { LogicRule, Question } from "@orksys-survey/db";
     4→import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
     5→import { Bolt, Loader2, Plus } from "lucide-react";
     6→import { useState } from "react";
     7→import { toast } from "sonner";
     8→import { Button } from "@/components/ui/button";
     9→import {
    10→	Dialog,
    11→	DialogContent,
    12→	DialogDescription,
    13→	DialogFooter,
    14→	DialogHeader,
    15→	DialogTitle,
    16→	DialogTrigger,
    17→} from "@/components/ui/dialog";
    18→import { orpc } from "@/utils/orpc";
    19→
    20→import { LogicRuleForm } from "./logic-rule-form";
    21→import { RuleListItem } from "./rule-list-item";
    22→
    23→interface LogicBuilderProps {
    24→	surveyId: string;
    25→	questions: Question[];
    26→	selectedQuestionId: string | null;
    27→}
    28→
    29→export function LogicBuilder({
    30→	surveyId,
    31→	questions,
    32→	selectedQuestionId,
    33→}: LogicBuilderProps) {
    34→	const queryClient = useQueryClient();
    35→	const [isDialogOpen, setIsDialogOpen] = useState(false);
    36→	const [editingRule, setEditingRule] = useState<LogicRule | null>(null);
    37→	const [deleteRuleId, setDeleteRuleId] = useState<string | null>(null);
    38→
    39→	const logicRules = useQuery(
    40→		orpc.logicRule.list.queryOptions({ input: { surveyId } }),
    41→	);
    42→
    43→	const deleteMutation = useMutation(
    44→		orpc.logicRule.delete.mutationOptions({
    45→			onSuccess: () => {
    46→				toast.success("Logic rule deleted");
    47→				queryClient.invalidateQueries({ queryKey: ["logicRule"] });
    48→				setDeleteRuleId(null);
    49→			},
    50→			onError: (error) => {
    51→				toast.error(error.message || "Failed to delete logic rule");
    52→			},
    53→		}),
    54→	);
    55→
    56→	// Filter rules for the selected question
    57→	const questionRules = selectedQuestionId
    58→		? logicRules.data?.filter(
    59→				(rule) => rule.sourceQuestionId === selectedQuestionId,
    60→			)
    61→		: [];
    62→
    63→	const handleDelete = (ruleId: string) => {
    64→		setDeleteRuleId(ruleId);
    65→	};
    66→
    67→	const confirmDelete = () => {
    68→		if (deleteRuleId) {
    69→			deleteMutation.mutate({ id: deleteRuleId });
    70→		}
    71→	};
    72→
    73→	const handleFormSuccess = () => {
    74→		setIsDialogOpen(false);
    75→		setEditingRule(null);
    76→		queryClient.invalidateQueries({ queryKey: ["logicRule"] });
    77→	};
    78→
    79→	if (!selectedQuestionId) {
    80→		return (
    81→			<div className="rounded-xl border border-primary/20 bg-primary/5 p-4">
    82→				<div className="mb-3 flex items-center gap-2">
    83→					<Bolt className="h-4 w-4 text-primary" />
    84→					<span className="font-semibold text-foreground text-sm">
    85→						Skip Logic
    86→					</span>
    87→				</div>
    88→				<p className="text-muted-foreground text-xs leading-relaxed">
    89→					Select a question to add skip logic.
