   123→
   124→				{survey.status === "draft" ? (
   125→					<Button onClick={handlePublish} disabled={publishMutation.isPending}>
   126→						{publishMutation.isPending ? (
   127→							<Loader2 className="mr-2 h-4 w-4 animate-spin" />
   128→						) : (
   129→							<Send className="mr-2 h-4 w-4" />
   130→						)}
   131→						Publish
   132→					</Button>
   133→				) : (
   134→					<Button
   135→						variant="outline"
   136→						render={
   137→							<a
   138→								href={`/s/${survey.slug}`}
   139→								target="_blank"
   140→								rel="noopener noreferrer"
   141→							/>
   142→						}
   143→					>
   144→						<Eye className="mr-2 h-4 w-4" />
   145→						View Survey
   146→					</Button>
   147→				)}
   148→			</div>
   149→
   150→			<SurveySettingsDialog
   151→				open={settingsOpen}
