    24→const createSurveySchema = z.object({
    25→	slug: z
    26→		.string()
    27→		.min(1, "Slug is required")
    28→		.max(100)
    29→		.regex(
    30→			/^[a-z0-9-]+$/,
    31→			"Slug can only contain lowercase letters, numbers, and hyphens",
    32→		),
    33→	title: z.string().min(1, "Title is required").max(255),
    34→	description: z.string().max(2000),
    35→});
    36→
    37→function generateSlug(title: string): string {
    38→	return title
    39→		.toLowerCase()
    40→		.replace(/[^a-z0-9]+/g, "-")
    41→		.replace(/^-|-$/g, "")
    42→		.slice(0, 50);
    43→}
