    60→	const form = useForm({
    61→		defaultValues: {
    62→			slug: "",
    63→			title: "",
    64→			description: "",
    65→		},
    66→		onSubmit: async ({ value }) => {
    67→			await createMutation.mutateAsync({
    68→				slug: value.slug || generateSlug(value.title),
    69→				title: value.title,
    70→				description: value.description || undefined,
    71→			});
    72→		},
    73→		validators: {
    74→			onSubmit: createSurveySchema,
    75→		},
    76→	});
    77→
    78→	return (
    79→		<div className="mx-auto w-full max-w-2xl p-6">
    80→			<div className="mb-6">
    81→				<Button variant="ghost" size="sm" render={<Link href="/surveys" />}>
    82→					<ArrowLeft className="mr-2 h-4 w-4" />
    83→					Back to Surveys
    84→				</Button>
    85→			</div>
    86→
    87→			<Card>
    88→				<CardHeader>
    89→					<CardTitle>Create New Survey</CardTitle>
    90→					<CardDescription>
    91→						Set up a new survey to start collecting responses
    92→					</CardDescription>
    93→				</CardHeader>
    94→				<CardContent>
    95→					<form
    96→						onSubmit={(e) => {
    97→							e.preventDefault();
    98→							e.stopPropagation();
    99→							form.handleSubmit();
   100→						}}
   101→						className="space-y-6"
   102→					>
   103→						<form.Field name="title">
   104→							{(field) => (
   105→								<div className="space-y-2">
   106→									<Label htmlFor={field.name}>Title *</Label>
   107→									<Input
   108→										id={field.name}
   109→										name={field.name}
   110→										placeholder="e.g., Customer Feedback Survey"
   111→										value={field.state.value}
   112→										onBlur={field.handleBlur}
   113→										onChange={(e) => {
   114→											field.handleChange(e.target.value);
   115→											// Auto-generate slug if empty
   116→											if (!form.getFieldValue("slug")) {
   117→												form.setFieldValue(
   118→													"slug",
   119→													generateSlug(e.target.value),
   120→												);
   121→											}
   122→										}}
   123→									/>
   124→									{field.state.meta.errors.length > 0 && (
   125→										<p className="text-destructive text-sm">
   126→											{String(field.state.meta.errors[0])}
   127→										</p>
   128→									)}
   129→								</div>
   130→							)}
   131→						</form.Field>
   132→
   133→						<form.Field name="slug">
   134→							{(field) => (
   135→								<div className="space-y-2">
   136→									<Label htmlFor={field.name}>URL Slug *</Label>
   137→									<div className="flex items-center">
   138→										<span className="shrink-0 rounded-l-md border border-r-0 bg-muted px-3 py-2 text-muted-foreground text-sm">
   139→											/survey/
   140→										</span>
   141→										<Input
   142→											id={field.name}
   143→											name={field.name}
   144→											placeholder="customer-feedback"
   145→											value={field.state.value}
   146→											onBlur={field.handleBlur}
   147→											onChange={(e) => field.handleChange(e.target.value)}
   148→											className="rounded-l-none"
   149→										/>
   150→									</div>
   151→									<p className="text-muted-foreground text-xs">
   152→										Unique identifier for your survey URL. Use lowercase
   153→										letters, numbers, and hyphens.
   154→									</p>
   155→									{field.state.meta.errors.length > 0 && (
   156→										<p className="text-destructive text-sm">
   157→											{String(field.state.meta.errors[0])}
   158→										</p>
   159→									)}
   160→								</div>
   161→							)}
   162→						</form.Field>
   163→
   164→						<form.Field name="description">
   165→							{(field) => (
   166→								<div className="space-y-2">
   167→									<Label htmlFor={field.name}>Description</Label>
   168→									<Textarea
   169→										id={field.name}
   170→										name={field.name}
   171→										placeholder="Describe the purpose of this survey..."
   172→										value={field.state.value}
   173→										onBlur={field.handleBlur}
   174→										onChange={(e) => field.handleChange(e.target.value)}
   175→										rows={3}
   176→									/>
   177→									{field.state.meta.errors.length > 0 && (
   178→										<p className="text-destructive text-sm">
   179→											{String(field.state.meta.errors[0])}
   180→										</p>
   181→									)}
   182→								</div>
   183→							)}
   184→						</form.Field>
   185→
   186→						<form.Subscribe>
   187→							{(state) => (
   188→								<div className="flex gap-3 pt-4">
   189→									<Button
   190→										type="button"
   191→										variant="outline"
   192→										onClick={() => router.push("/surveys")}
   193→									>
   194→										Cancel
   195→									</Button>
   196→									<Button
   197→										type="submit"
   198→										disabled={!state.canSubmit || state.isSubmitting}
   199→									>
   200→										{state.isSubmitting ? (
   201→											<>
   202→												<Loader2 className="mr-2 h-4 w-4 animate-spin" />
   203→												Creating...
   204→											</>
   205→										) : (
   206→											"Create Survey"
   207→										)}
   208→									</Button>
   209→								</div>
   210→							)}
   211→						</form.Subscribe>
   212→					</form>
   213→				</CardContent>
   214→			</Card>
   215→		</div>
   216→	);
   217→}
