"use client";

import Link from "next/link";

import { ModeToggle } from "@/components/mode-toggle";
import OrganizationSwitcher from "@/components/organization-switcher";
import UserMenu from "@/components/user-menu";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/lib/utils";

import { AppHeaderProvider } from "./context";
import { Breadcrumb } from "./breadcrumb";
import { HeaderNav } from "./header-nav";
import { MobileMenu } from "./mobile-menu";
import type { AppHeaderProps } from "./types";

function AppHeaderInner({
	showOrgSwitcher = true,
	showThemeToggle = true,
	showUserMenu = true,
	breadcrumbs = [],
	sticky = true,
	border = "bottom",
	className,
}: Omit<AppHeaderProps, "navItems" | "children">) {
	return (
		<header
			className={cn(
				"bg-card/80 backdrop-blur-sm z-50 flex h-14 items-center px-4",
				sticky && "sticky top-0",
				border === "bottom" && "border-b",
				border === "full" && "border-b shadow-sm",
				className,
			)}
		>
			{/* Left section: Mobile menu + Logo */}
			<div className="flex items-center gap-2">
				<MobileMenu />
				<Link
					href="/dashboard"
					className="font-bold text-lg tracking-tight text-foreground hover:text-primary transition-colors"
				>
					orksys
				</Link>
			</div>

			{/* Centered desktop navigation */}
			<div className="flex flex-1 justify-center">
				<HeaderNav />
			</div>

			{/* Right actions */}
			<div className="flex items-center gap-2">
				{showOrgSwitcher && <OrganizationSwitcher />}
				{showThemeToggle && <ModeToggle />}
				<Separator orientation="vertical" className="h-6" />
				{showUserMenu && <UserMenu />}
			</div>

			{/* Breadcrumbs - shown below header */}
			{breadcrumbs.length > 0 && (
				<div className="absolute top-full left-0 right-0 flex h-10 items-center border-b bg-card/80 backdrop-blur-sm px-4">
					<Breadcrumb items={breadcrumbs} />
				</div>
			)}
		</header>
	);
}

export function AppHeader({ navItems = [], ...props }: AppHeaderProps) {
	return (
		<AppHeaderProvider navItems={navItems}>
			<AppHeaderInner {...props} />
		</AppHeaderProvider>
	);
}

